describe('Badge Count of Selected Rows', () => {
    beforeEach(() => {
        cy.visit('/table-list'); // Adjust the URL to your application's route
    });

    it('should display the correct badge count when rows are selected', () => {
        // Select multiple rows
        cy.get('.table-row').first().check(); // Assuming check() is used for selecting rows
        cy.get('.table-row').eq(1).check();

        // Verify the badge count
        cy.get('.badge-count').should('contain', '2'); // Assuming the badge count element has this class
    });

    it('should display zero when no rows are selected', () => {
        // Ensure no rows are selected
        cy.get('.table-row').uncheck({ force: true }); // Uncheck all rows if any are checked

        // Verify the badge count
        cy.get('.badge-count').should('contain', '0');
    });
});
